/* ════════════════════════════════════════════════════════════
   BREW & BLOOM CAFÉ — style.css
   Brand palette:
   --cream:       #fdf6ed   (warm cream background)
   --espresso:    #3b1f0e   (dark espresso brown)
   --latte:       #8b5a2b   (medium latte brown)
   --caramel:     #c4721e   (terracotta orange / caramel)
   --sage:        #6b8e6b   (muted sage green)
   --sage-light:  #e8f0e8   (soft sage tint)
   --sand:        #f0e4d0   (warm sand card bg)
   ════════════════════════════════════════════════════════════ */

/* ── RESET & CUSTOM PROPERTIES ─────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --cream:       #fdf6ed;
  --cream-dark:  #f5e9d5;
  --espresso:    #3b1f0e;
  --espresso-2:  #2a1508;
  --latte:       #8b5a2b;
  --caramel:     #c4721e;
  --caramel-lt:  #e8a050;
  --sage:        #6b8e6b;
  --sage-lt:     #e8f0e8;
  --sand:        #f0e4d0;
  --sand-dark:   #e5d3b8;
  --white:       #ffffff;
  --text:        #2d1a0e;
  --text-muted:  #7a5a3a;
  --radius-sm:   8px;
  --radius-md:   14px;
  --radius-lg:   22px;
  --radius-xl:   32px;
  --shadow-sm:   0 2px 8px rgba(59,31,14,.08);
  --shadow-md:   0 6px 24px rgba(59,31,14,.12);
  --shadow-lg:   0 16px 48px rgba(59,31,14,.16);
  --nav-h:       72px;
  --transition:  0.3s cubic-bezier(0.4,0,0.2,1);
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: var(--nav-h);
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: 'Inter', sans-serif;
  background: var(--cream);
  color: var(--text);
  line-height: 1.65;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul { list-style: none; }
address { font-style: normal; }

/* ── TYPOGRAPHY ────────────────────────────────────────── */
h1, h2, h3, h4, h5 {
  font-family: 'Playfair Display', serif;
  line-height: 1.25;
  color: var(--espresso);
}

.section-eyebrow {
  font-family: 'Dancing Script', cursive;
  font-size: 1.25rem;
  color: var(--caramel);
  display: block;
  margin-bottom: 0.4rem;
}

.section-title {
  font-size: clamp(2rem, 4vw, 2.8rem);
  font-weight: 700;
  margin-bottom: 1rem;
}

.section-desc {
  color: var(--text-muted);
  max-width: 56ch;
  margin: 0 auto;
}

.section-header {
  text-align: center;
  margin-bottom: 3rem;
}

/* ── CONTAINER ─────────────────────────────────────────── */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* ── SECTION ───────────────────────────────────────────── */
.section {
  padding: 5rem 0;
}

/* ── BUTTONS ───────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.7rem 1.6rem;
  border-radius: 100px;
  font-weight: 600;
  font-size: 0.925rem;
  letter-spacing: 0.02em;
  transition: all var(--transition);
  white-space: nowrap;
  cursor: pointer;
  border: 2px solid transparent;
}

.btn-lg {
  padding: 0.9rem 2rem;
  font-size: 1rem;
}

.btn-sm {
  padding: 0.45rem 1.1rem;
  font-size: 0.8rem;
}

.btn-primary {
  background: var(--espresso);
  color: var(--cream);
  border-color: var(--espresso);
}
.btn-primary:hover, .btn-primary:focus-visible {
  background: var(--caramel);
  border-color: var(--caramel);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(196,114,30,.35);
}

.btn-ghost {
  background: rgba(255,255,255,0.12);
  color: var(--white);
  border-color: rgba(255,255,255,0.5);
  backdrop-filter: blur(8px);
}
.btn-ghost:hover, .btn-ghost:focus-visible {
  background: rgba(255,255,255,0.22);
  border-color: rgba(255,255,255,0.9);
  transform: translateY(-2px);
}

.btn-whatsapp {
  background: #25D366;
  color: #fff;
  border-color: #25D366;
  font-weight: 700;
}
.btn-whatsapp:hover, .btn-whatsapp:focus-visible {
  background: #128C7E;
  border-color: #128C7E;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(37,211,102,.4);
}

.btn-order {
  background: var(--caramel);
  color: #fff;
  border-color: var(--caramel);
  padding: 0.4rem 1rem;
  font-size: 0.78rem;
}
.btn-order:hover, .btn-order:focus-visible {
  background: var(--espresso);
  border-color: var(--espresso);
  transform: translateY(-1px);
}

/* Focus styles for accessibility */
:focus-visible {
  outline: 3px solid var(--caramel);
  outline-offset: 3px;
}

/* ════════════════════════════════════════════════════════════
   NAVIGATION
   ════════════════════════════════════════════════════════════ */
.navbar {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  height: var(--nav-h);
  background: transparent;
  transition: background var(--transition), box-shadow var(--transition);
}

.navbar.scrolled {
  background: rgba(253,246,237,0.96);
  backdrop-filter: blur(16px);
  box-shadow: 0 1px 0 rgba(59,31,14,.08), var(--shadow-sm);
}

.nav-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-shrink: 0;
  text-decoration: none;
}

.logo-icon {
  font-size: 1.8rem;
  line-height: 1;
  filter: drop-shadow(0 2px 4px rgba(0,0,0,.15));
}

.logo-text {
  display: flex;
  flex-direction: column;
  line-height: 1;
}

.logo-name {
  font-family: 'Playfair Display', serif;
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--espresso);
  transition: color var(--transition);
}

.navbar:not(.scrolled) .logo-name,
.navbar:not(.scrolled) .logo-tagline {
  color: var(--white);
}

.logo-tagline {
  font-size: 0.55rem;
  letter-spacing: 0.25em;
  font-weight: 500;
  color: var(--latte);
  margin-top: 1px;
}

.navbar:not(.scrolled) .logo-tagline { color: rgba(255,255,255,0.7); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  margin-left: auto;
}

.nav-link {
  padding: 0.4rem 0.85rem;
  border-radius: 100px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--espresso);
  transition: all var(--transition);
  position: relative;
}

.navbar:not(.scrolled) .nav-link { color: rgba(255,255,255,0.9); }
.navbar:not(.scrolled) .nav-link:hover,
.navbar:not(.scrolled) .nav-link.active {
  color: #fff;
  background: rgba(255,255,255,0.15);
}

.nav-link:hover, .nav-link.active {
  color: var(--caramel);
  background: rgba(196,114,30,.08);
}

.nav-cta {
  flex-shrink: 0;
  font-size: 0.85rem;
  padding: 0.5rem 1.2rem;
}

.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 40px;
  height: 40px;
  padding: 6px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.ham-bar {
  display: block;
  width: 100%;
  height: 2px;
  background: var(--espresso);
  border-radius: 2px;
  transition: all var(--transition);
}

.navbar:not(.scrolled) .ham-bar { background: #fff; }

.hamburger.open .ham-bar:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open .ham-bar:nth-child(2) { opacity: 0; transform: scaleX(0); }
.hamburger.open .ham-bar:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* ════════════════════════════════════════════════════════════
   HERO
   ════════════════════════════════════════════════════════════ */
.hero {
  position: relative;
  min-height: 100dvh;
  display: flex;
  align-items: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    url('https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?w=1920&q=80&auto=format&fit=crop') center/cover no-repeat;
  transform: scale(1.05);
  transition: transform 8s ease-out;
  will-change: transform;
}

.hero:hover .hero-bg { transform: scale(1.0); }

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(42,21,8,0.78) 0%,
    rgba(59,31,14,0.6) 50%,
    rgba(42,21,8,0.45) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
  padding-top: var(--nav-h);
  width: 100%;
}

.hero-eyebrow {
  font-family: 'Dancing Script', cursive;
  font-size: 1.4rem;
  color: var(--caramel-lt);
  display: block;
  margin-bottom: 1rem;
  opacity: 0;
  animation: fadeUp 0.7s 0.3s forwards;
}

.hero-headline {
  font-size: clamp(2.6rem, 6vw, 4.5rem);
  font-weight: 700;
  color: var(--white);
  line-height: 1.15;
  margin-bottom: 1.5rem;
  opacity: 0;
  animation: fadeUp 0.7s 0.5s forwards;
}

.hero-headline em {
  font-style: italic;
  color: var(--caramel-lt);
}

.hero-desc {
  color: rgba(255,255,255,0.82);
  font-size: 1.1rem;
  max-width: 50ch;
  margin-bottom: 2.2rem;
  line-height: 1.7;
  opacity: 0;
  animation: fadeUp 0.7s 0.7s forwards;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 3rem;
  opacity: 0;
  animation: fadeUp 0.7s 0.9s forwards;
}

.hero-badges {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  opacity: 0;
  animation: fadeUp 0.7s 1.1s forwards;
}

.badge {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.badge-num {
  font-family: 'Playfair Display', serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--caramel-lt);
}

.badge-label {
  font-size: 0.75rem;
  color: rgba(255,255,255,0.65);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.badge-sep {
  width: 1px;
  height: 36px;
  background: rgba(255,255,255,0.2);
}

.hero-scroll-hint {
  position: absolute;
  bottom: 2.5rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  color: rgba(255,255,255,0.5);
  font-size: 0.65rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  animation: fadeUp 1s 1.5s forwards;
  opacity: 0;
}

.scroll-arrow {
  width: 20px;
  height: 20px;
  border-right: 2px solid rgba(255,255,255,0.4);
  border-bottom: 2px solid rgba(255,255,255,0.4);
  transform: rotate(45deg);
  animation: bounce 1.5s ease infinite;
}

/* ════════════════════════════════════════════════════════════
   ANNOUNCEMENT STRIP
   ════════════════════════════════════════════════════════════ */
.announcement-strip {
  background: var(--espresso);
  padding: 0.7rem 0;
  overflow: hidden;
  white-space: nowrap;
}

.strip-track {
  display: inline-flex;
  animation: marquee 28s linear infinite;
}

.strip-track span {
  color: var(--caramel-lt);
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.03em;
  padding-right: 2rem;
}

/* ════════════════════════════════════════════════════════════
   MENU SECTION
   ════════════════════════════════════════════════════════════ */
.menu-section {
  background: var(--cream);
}

.menu-tabs {
  display: flex;
  gap: 0.5rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 2.5rem;
  background: var(--sand);
  border-radius: var(--radius-xl);
  padding: 0.4rem;
  max-width: 680px;
  margin-left: auto;
  margin-right: auto;
}

.tab-btn {
  padding: 0.55rem 1.2rem;
  border-radius: 100px;
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--latte);
  background: transparent;
  transition: all var(--transition);
  border: none;
  cursor: pointer;
  white-space: nowrap;
}

.tab-btn.active, .tab-btn:hover {
  background: var(--espresso);
  color: var(--cream);
  box-shadow: var(--shadow-sm);
}

.tab-panel { display: none; }
.tab-panel.active { display: block; animation: fadeIn 0.4s ease; }

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.5rem;
}

.menu-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
}

.menu-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lg);
}

.menu-card.featured-item {
  border: 2px solid var(--caramel);
}

.menu-card-img {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.menu-emoji {
  font-size: 3.5rem;
  filter: drop-shadow(0 4px 12px rgba(0,0,0,0.3));
  transition: transform var(--transition);
}

.menu-card:hover .menu-emoji { transform: scale(1.15) rotate(-3deg); }

.featured-tag {
  position: absolute;
  top: 0.6rem;
  right: 0.6rem;
  background: var(--caramel);
  color: #fff;
  font-size: 0.65rem;
  font-weight: 700;
  padding: 0.25rem 0.6rem;
  border-radius: 100px;
  letter-spacing: 0.03em;
}

.menu-card-body {
  padding: 1.2rem 1.25rem 1.25rem;
}

.menu-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.4rem;
}

.menu-item-name {
  font-family: 'Playfair Display', serif;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--espresso);
}

.menu-badge {
  flex-shrink: 0;
  background: var(--sand);
  color: var(--latte);
  font-size: 0.65rem;
  font-weight: 600;
  padding: 0.2rem 0.55rem;
  border-radius: 100px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.menu-badge.badge-special { background: #fff4e6; color: var(--caramel); }
.menu-badge.badge-cold    { background: #e6f4ff; color: #2272a8; }
.menu-badge.badge-fresh   { background: #eef5ee; color: var(--sage); }

.menu-item-desc {
  font-size: 0.82rem;
  color: var(--text-muted);
  line-height: 1.5;
  margin-bottom: 1rem;
}

.menu-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.menu-price {
  font-family: 'Playfair Display', serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--caramel);
}

.menu-disclaimer {
  text-align: center;
  margin-top: 2.5rem;
  color: var(--text-muted);
  font-size: 0.82rem;
  background: var(--sand);
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-md);
  display: inline-block;
  width: 100%;
  max-width: 660px;
  margin-left: auto;
  margin-right: auto;
}

/* ════════════════════════════════════════════════════════════
   ABOUT SECTION
   ════════════════════════════════════════════════════════════ */
.about-section {
  background: var(--cream-dark);
}

.about-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.about-imagery {
  position: relative;
  height: 520px;
}

.about-img-main {
  position: absolute;
  top: 0; left: 0;
  width: 75%;
  height: 78%;
  border-radius: var(--radius-xl);
  background: linear-gradient(160deg, #3b1f0e 0%, #8b5a2b 50%, #c4721e 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  background-image: url('https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?w=800&q=80&auto=format&fit=crop');
  background-size: cover;
  background-position: center;
}

.about-img-accent {
  position: absolute;
  bottom: 0; right: 0;
  width: 52%;
  height: 48%;
  border-radius: var(--radius-lg);
  background: linear-gradient(160deg, #5c3317 0%, #c4721e 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-lg);
  border: 4px solid var(--cream-dark);
  overflow: hidden;
  background-image: url('https://images.unsplash.com/photo-1447933601403-0c6688de566e?w=600&q=80&auto=format&fit=crop');
  background-size: cover;
  background-position: center;
}

.about-img-icon {
  font-size: 3.5rem;
  filter: drop-shadow(0 4px 12px rgba(0,0,0,.4));
}

.about-stat-card {
  position: absolute;
  top: 50%;
  right: 0;
  transform: translate(20%, -50%);
  background: var(--espresso);
  color: var(--cream);
  padding: 1rem 1.4rem;
  border-radius: var(--radius-md);
  text-align: center;
  box-shadow: var(--shadow-md);
  z-index: 2;
}

.stat-num {
  display: block;
  font-family: 'Playfair Display', serif;
  font-size: 2rem;
  font-weight: 700;
  color: var(--caramel-lt);
  line-height: 1;
}

.stat-label {
  font-size: 0.7rem;
  opacity: 0.8;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-top: 0.25rem;
}

.about-content { max-width: 520px; }

.about-para {
  color: var(--text-muted);
  margin-bottom: 1.25rem;
  line-height: 1.75;
}

.about-values {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin: 2rem 0;
}

.value-item {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
}

.value-icon {
  font-size: 1.6rem;
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  background: var(--sand);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.value-item strong {
  display: block;
  font-size: 0.95rem;
  color: var(--espresso);
  margin-bottom: 0.15rem;
}

.value-item p {
  font-size: 0.82rem;
  color: var(--text-muted);
}

/* ════════════════════════════════════════════════════════════
   GALLERY SECTION
   ════════════════════════════════════════════════════════════ */
.gallery-section {
  background: var(--espresso-2);
  padding: 5rem 0;
}

.gallery-section .section-eyebrow { color: var(--caramel-lt); }
.gallery-section .section-title   { color: var(--cream); }
.gallery-section .section-desc    { color: rgba(255,255,255,0.55); }

.gallery-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: auto auto;
  gap: 1rem;
}

.gallery-item {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  cursor: pointer;
  min-height: 220px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.gallery-tall {
  grid-row: span 2;
  min-height: 460px;
}

.gallery-wide {
  grid-column: span 2;
}

.gallery-bg {
  position: absolute;
  inset: 0;
  transition: transform 0.6s ease;
}

.gallery-item:hover .gallery-bg { transform: scale(1.06); }

.gallery-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(42,21,8,.75) 0%, transparent 60%);
  opacity: 0;
  transition: opacity var(--transition);
  display: flex;
  align-items: flex-end;
  padding: 1.25rem;
}

.gallery-item:hover .gallery-overlay,
.gallery-item:focus-visible .gallery-overlay { opacity: 1; }

.gallery-label {
  color: #fff;
  font-family: 'Playfair Display', serif;
  font-size: 1.05rem;
  font-weight: 600;
}

.gallery-emoji {
  font-size: 3.5rem;
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 4px 16px rgba(0,0,0,.4));
  transition: transform 0.5s ease;
}

.gallery-item:hover .gallery-emoji { transform: scale(1.2); }

/* ════════════════════════════════════════════════════════════
   BESTSELLERS SECTION
   ════════════════════════════════════════════════════════════ */
.bestsellers-section {
  background: var(--sand);
}

.bestsellers-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 1.5rem;
}

.bestseller-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition), box-shadow var(--transition);
}

.bestseller-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--shadow-lg);
}

.bestseller-img {
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.bestseller-emoji {
  font-size: 4rem;
  filter: drop-shadow(0 4px 16px rgba(0,0,0,.3));
  transition: transform var(--transition);
}

.bestseller-card:hover .bestseller-emoji { transform: scale(1.15) rotate(-5deg); }

.bestseller-rank {
  position: absolute;
  top: 0.8rem;
  left: 0.8rem;
  background: rgba(0,0,0,0.5);
  color: #fff;
  font-family: 'Playfair Display', serif;
  font-size: 0.9rem;
  font-weight: 700;
  padding: 0.3rem 0.7rem;
  border-radius: 100px;
  backdrop-filter: blur(4px);
}

.bestseller-body {
  padding: 1.25rem;
}

.bestseller-body h3 {
  font-size: 1.1rem;
  margin-bottom: 0.3rem;
}

.bestseller-body p {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-bottom: 1rem;
}

.bestseller-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

/* ════════════════════════════════════════════════════════════
   LOCATION SECTION
   ════════════════════════════════════════════════════════════ */
.location-section {
  background: var(--cream);
}

.location-grid {
  display: grid;
  grid-template-columns: 1fr 1.4fr;
  gap: 3rem;
  align-items: start;
}

.location-info {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.info-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  display: flex;
  gap: 1rem;
  align-items: flex-start;
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition);
}

.info-card:hover { box-shadow: var(--shadow-md); }

.info-icon {
  font-size: 1.6rem;
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  background: var(--sand);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.info-card h3 {
  font-size: 1rem;
  margin-bottom: 0.4rem;
}

.info-card p {
  color: var(--text-muted);
  font-size: 0.88rem;
  line-height: 1.6;
}

.info-card a {
  color: var(--caramel);
  transition: color var(--transition);
}

.info-card a:hover { color: var(--espresso); }

.hours-grid {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.15rem 1rem;
  font-size: 0.85rem;
  color: var(--text-muted);
}

.demo-note {
  display: block;
  margin-top: 0.5rem;
  font-size: 0.73rem;
  color: var(--latte);
  background: var(--sand);
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  width: fit-content;
}

.map-container {
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.map-placeholder {
  height: 420px;
  background: linear-gradient(160deg, #3b1f0e 0%, #6b3a1f 60%, #c4721e 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-xl);
}

.map-inner {
  text-align: center;
  color: #fff;
}

.map-pin { font-size: 3rem; display: block; margin-bottom: 0.5rem; }
.map-title {
  font-family: 'Playfair Display', serif;
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.25rem;
}
.map-sub {
  opacity: 0.7;
  margin-bottom: 1.5rem;
  font-size: 0.9rem;
}

.map-btn {
  background: #fff;
  color: var(--espresso);
  border-color: #fff;
}
.map-btn:hover { background: var(--cream); border-color: var(--cream); }

/* ════════════════════════════════════════════════════════════
   CONTACT SECTION
   ════════════════════════════════════════════════════════════ */
.contact-section {
  background: var(--cream-dark);
}

.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.contact-desc {
  color: var(--text-muted);
  margin-bottom: 2rem;
  max-width: 46ch;
  line-height: 1.7;
}

.contact-items {
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
  margin-bottom: 2rem;
}

.contact-item {
  display: flex;
  gap: 1rem;
  align-items: flex-start;
}

.contact-icon {
  font-size: 1.4rem;
  width: 44px;
  height: 44px;
  background: var(--sand);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.contact-item strong {
  display: block;
  font-size: 0.9rem;
  color: var(--espresso);
  margin-bottom: 0.15rem;
}

.contact-item p, .contact-item a {
  font-size: 0.88rem;
  color: var(--text-muted);
}

.contact-item a:hover { color: var(--caramel); }

.whatsapp-cta-block { margin-top: 2rem; }

.whatsapp-cta-block p {
  font-size: 0.82rem;
  color: var(--text-muted);
  margin-bottom: 0.6rem;
}

.contact-visual {
  display: flex;
  justify-content: center;
}

.contact-card-visual {
  background: linear-gradient(160deg, #3b1f0e, #8b5a2b, #c4721e);
  border-radius: var(--radius-xl);
  padding: 3rem 2.5rem;
  text-align: center;
  color: #fff;
  max-width: 380px;
  width: 100%;
  box-shadow: var(--shadow-lg);
  position: relative;
  overflow: hidden;
}

.contact-card-visual::before {
  content: '';
  position: absolute;
  top: -60px; right: -60px;
  width: 200px; height: 200px;
  background: rgba(255,255,255,0.06);
  border-radius: 50%;
}

.cv-emoji {
  font-size: 5rem;
  display: block;
  margin-bottom: 1.5rem;
  filter: drop-shadow(0 8px 24px rgba(0,0,0,.3));
}

.cv-quote p {
  font-family: 'Playfair Display', serif;
  font-style: italic;
  font-size: 1.1rem;
  line-height: 1.65;
  color: rgba(255,255,255,0.9);
}

/* ════════════════════════════════════════════════════════════
   FOOTER
   ════════════════════════════════════════════════════════════ */
.footer {
  background: var(--espresso-2);
  padding: 4rem 0 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1.4fr;
  gap: 3rem;
  padding-bottom: 3rem;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.footer-brand-desc {
  color: rgba(255,255,255,0.5);
  font-size: 0.85rem;
  margin-top: 0.8rem;
  margin-bottom: 1.5rem;
  max-width: 28ch;
  line-height: 1.65;
}

.footer-logo .logo-name { color: var(--cream); }
.footer-logo .logo-tagline { color: rgba(255,255,255,0.45); }

.social-links {
  display: flex;
  gap: 0.6rem;
}

.social-link {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.6);
  transition: all var(--transition);
}

.social-link:hover {
  background: var(--caramel);
  color: #fff;
  transform: translateY(-3px);
}

.footer-heading {
  font-family: 'Inter', sans-serif;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: rgba(255,255,255,0.35);
  margin-bottom: 1.25rem;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.footer-links a {
  color: rgba(255,255,255,0.55);
  font-size: 0.87rem;
  transition: color var(--transition);
}

.footer-links a:hover { color: var(--caramel-lt); }

.footer-address p {
  color: rgba(255,255,255,0.55);
  font-size: 0.85rem;
  line-height: 1.6;
  margin-bottom: 0.5rem;
}

.footer-bottom {
  padding: 1.5rem 0;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.footer-bottom p {
  font-size: 0.78rem;
  color: rgba(255,255,255,0.3);
  text-align: center;
}

.footer-disclaimer {
  font-size: 0.72rem !important;
  max-width: 65ch;
  margin: 0 auto;
  line-height: 1.5;
}

/* ════════════════════════════════════════════════════════════
   BACK TO TOP
   ════════════════════════════════════════════════════════════ */
.back-to-top {
  position: fixed;
  bottom: 2rem;
  right: 2rem;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: var(--espresso);
  color: var(--cream);
  font-size: 1.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-md);
  opacity: 0;
  transform: translateY(20px);
  transition: all var(--transition);
  pointer-events: none;
  z-index: 900;
}

.back-to-top.visible {
  opacity: 1;
  transform: translateY(0);
  pointer-events: all;
}

.back-to-top:hover {
  background: var(--caramel);
  transform: translateY(-3px);
}

/* ════════════════════════════════════════════════════════════
   ANIMATIONS
   ════════════════════════════════════════════════════════════ */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(24px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

@keyframes bounce {
  0%, 100% { transform: rotate(45deg) translateY(0); }
  50%       { transform: rotate(45deg) translateY(6px); }
}

@keyframes marquee {
  0%   { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* Scroll-triggered reveal */
.reveal {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}
.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ════════════════════════════════════════════════════════════
   RESPONSIVE — TABLET  (≤ 900px)
   ════════════════════════════════════════════════════════════ */
@media (max-width: 900px) {
  :root { --nav-h: 64px; }

  .nav-links, .nav-cta {
    display: none;
  }

  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: var(--nav-h);
    left: 0; right: 0;
    background: rgba(253,246,237,0.98);
    backdrop-filter: blur(20px);
    padding: 1.5rem;
    gap: 0.25rem;
    border-bottom: 1px solid var(--sand-dark);
    box-shadow: var(--shadow-lg);
    z-index: 999;
  }

  .nav-links.open .nav-link {
    display: block;
    padding: 0.75rem 1rem;
    border-radius: var(--radius-md);
    font-size: 1rem;
  }

  .hamburger { display: flex; margin-left: auto; }

  .about-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .about-imagery {
    height: 320px;
  }

  .about-stat-card {
    transform: none;
    right: 0.5rem;
    top: auto;
    bottom: -1rem;
  }

  .location-grid {
    grid-template-columns: 1fr;
  }

  .contact-grid {
    grid-template-columns: 1fr;
  }

  .contact-visual { display: none; }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
  }

  .gallery-grid {
    grid-template-columns: 1fr 1fr;
  }

  .gallery-tall { grid-row: span 1; min-height: 220px; }
  .gallery-wide { grid-column: span 2; }
}

/* ════════════════════════════════════════════════════════════
   RESPONSIVE — MOBILE  (≤ 600px)
   ════════════════════════════════════════════════════════════ */
@media (max-width: 600px) {
  .section { padding: 3.5rem 0; }

  .hero-badges { flex-wrap: wrap; gap: 1rem; }

  .menu-grid {
    grid-template-columns: 1fr;
  }

  .menu-tabs {
    padding: 0.3rem;
    gap: 0.25rem;
  }

  .tab-btn {
    padding: 0.45rem 0.8rem;
    font-size: 0.8rem;
  }

  .about-imagery { height: 260px; }

  .gallery-grid {
    grid-template-columns: 1fr;
  }

  .gallery-tall, .gallery-wide {
    grid-row: span 1;
    grid-column: span 1;
    min-height: 200px;
  }

  .bestsellers-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .back-to-top {
    bottom: 1.2rem;
    right: 1.2rem;
    width: 40px;
    height: 40px;
  }

  .hero-actions {
    flex-direction: column;
    align-items: flex-start;
  }

  .contact-grid { gap: 2rem; }
}

@media (max-width: 400px) {
  .bestsellers-grid { grid-template-columns: 1fr; }
}

